def run_termination(stage: dict, coverage_entries: list[dict]) -> dict:
    """Combine stage authority with typed Coverage (native-evidence.md section 10: fault law and whole-Run route).

    A faulted or cancelled stage keeps its own D9 termination and mints nothing. Otherwise the Run's PRIMARY
    deficiency is the most specific, by section 10 precedence, among the entries' declared deficiencies and the one a
    clean typed stage terminal implies (BudgetExhausted -> budget-exhausted, Unavailable -> provider-unavailable),
    and its termination is `native_deficiency_d9` of it: indeterminate 3 under an existing D9 code, never a fault and
    never exit 0. typedDetail names the most specific deficiency an entry actually carries (the coverage2 record)
    and every nativeCause those entries carry, whatever the stage kind. SCOPE: ONE primary code is returned; the D9
    ordered reasonCodes with secondaryDeficiencies (d9-exit-contract causeModel.codeDerivation) are composed by the
    host termination and are not produced here.
    """
    if stage["authority"] == "none":
        return {"authority": "none", "runSealed": False, "factsMinted": 0, "d9": stage["d9"], "typedDetail": None}
    deficient = [e for e in coverage_entries if e.get("deficiency")]
    candidates = [e["deficiency"] for e in deficient]
    if stage.get("terminalKind") in STAGE_TERMINAL_DEFICIENCY:
        candidates.append(STAGE_TERMINAL_DEFICIENCY[stage["terminalKind"]])
    d9 = stage["d9"]
    if candidates:
        route = native_deficiency_d9(min(candidates, key=PRECEDENCE_V2.index))
        d9 = {"class": route["class"], "exitCode": route["exitCode"], "code": route["code"]}
    typed = None
    if deficient:
        typed = {"carrier": _TYPED_DETAIL, "deficiency": min((e["deficiency"] for e in deficient), key=PRECEDENCE_V2.index),
                 "nativeCauses": sorted({e.get("nativeCause") for e in deficient if e.get("nativeCause")})}
    return {"authority": "authoritative", "runSealed": True, "factsMinted": len(coverage_entries), "d9": d9, "typedDetail": typed}

